package typeoracle

type Source int64; type Callback func(Source) Counter; type OtherCallback func(Source) OtherCounter; type ShapeCallback func(Origin) Target; type OtherShapeCallback func(Origin) OtherTarget
type Counter int8
func (value Counter) Use(n int) {}
type OtherCounter int64
func (value OtherCounter) Use(n int) {}
type Origin struct{ Value int `origin` }
type Target struct{ Value int `target` }
func (value Target) Visit(n int) {}
type OtherTarget struct{ Value int `other` }
func (value OtherTarget) Visit(n int) {}
func Navigate(value Source, shape Origin) {
 checked := Callback(func(Source) Counter { return 0 })(value)
 checked.Use(1)
 converted := ShapeCallback(func(Origin) Target { return Target{} })(shape)
 converted.Visit(2)
}

